import logging

logger = logging.getLogger(__name__)

def process_payment(user_id: int, amount: float, db: sqlite3.Connection) -> bool:
    if not isinstance(user_id, int) or user_id <= 0:
        raise ValueError("user_id debe ser entero positivo")
    if not isinstance(amount, (int, float)) or amount <= 0:
        raise ValueError("amount debe ser número positivo")

    try:
        user = db.execute("SELECT * FROM users WHERE id = ?", (user_id,)).fetchone()
        if not user:
            logger.warning(f"Usuario {user_id} no encontrado")
            return False

        card_ids = user['card_ids']
        if not card_ids:
            return False

        # Batch query para cards
        placeholders = ','.join('?' * len(card_ids))
        cards = db.execute(f"SELECT * FROM cards WHERE id IN ({placeholders})", card_ids).fetchall()

        for card in cards:
            if card['balance'] >= amount:
                db.execute("UPDATE cards SET balance = balance - ? WHERE id = ?", (amount, card['id']))
                logger.info(f"Pago de {amount} procesado con card {card['id']}")
                return True

        logger.info(f"Ninguna card tiene balance suficiente para pago de {amount}")
        return False

    except sqlite3.Error as e:
        logger.error(f"Error de DB procesando pago para usuario {user_id}: {e}")
        raise

