from abc import ABC, abstractmethod

class DiscountStrategy(ABC):
    @abstractmethod
    def apply(self, price: float) -> float:
        pass

class PremiumDiscount(DiscountStrategy):
    def apply(self, price: float) -> float:
        return price * 0.8

class RegularDiscount(DiscountStrategy):
    def apply(self, price: float) -> float:
        return price

class DiscountCalculator:
    def __init__(self):
        self.strategies = {
            'premium': PremiumDiscount(),
            'regular': RegularDiscount()
        }

    def calculate(self, price: float, customer_type: str) -> float:
        if customer_type not in self.strategies:
            raise ValueError(f"Unknown customer type: {customer_type}")
        return self.strategies[customer_type].apply(price)

# Wrapper para mantener API compatible
def calculate_discount(price: float, customer_type: str) -> float:
    calculator = DiscountCalculator()
    return calculator.calculate(price, customer_type)

