    for x in data:
        total += x
    return total

def calculate_avg(data, total):
    return total / len(data) if data else 0

def find_max(data):
    if not data:
        return None
    max_val = data[0]
    for x in data:
        if x > max_val:
            max_val = x
    return max_val

def find_min(data):
